-- 场景 1：隐式类型转换导致索引失效
-- phone 是 varchar 列，用数字查询会触发 CAST，索引失效
EXPLAIN SELECT * FROM users WHERE phone = 13800000000;
-- 修复：用字符串查询
EXPLAIN SELECT * FROM users WHERE phone = '13800000000';

-- 场景 2：函数运算导致索引失效
EXPLAIN SELECT * FROM orders WHERE YEAR(created_at) = 2025;
-- 修复：改为范围条件
EXPLAIN SELECT * FROM orders
WHERE created_at >= '2025-01-01' AND created_at < '2026-01-01';

-- 场景 3：前导模糊匹配导致索引失效
EXPLAIN SELECT * FROM products WHERE name LIKE '%abc';
-- 后缀模糊匹配可以走索引
EXPLAIN SELECT * FROM products WHERE name LIKE 'abc%';
